begin;
alter policy nl_admin_coach_update on public.player_data using(nextlevel_private.is_admin_coach() and (module in ('perfil_v1','mini_profile_v1','foto_url','profile_dorsal_v1','obj_estados_v1','coach_eval_v1') or starts_with(module,'plan_progress_v1:') or starts_with(module,'mini_measures_v1:') or starts_with(module,'gradual_goals_v1:'))) with check(nextlevel_private.is_admin_coach() and exists(select 1 from public.players p where p.id=player_id) and ((module in ('perfil_v1','mini_profile_v1','foto_url','profile_dorsal_v1','obj_estados_v1') or starts_with(module,'plan_progress_v1:') or starts_with(module,'mini_measures_v1:') or starts_with(module,'gradual_goals_v1:')) or (module='coach_eval_v1' and data->>'author_id'=auth.uid()::text and data->>'author_type'='coach')));
commit;
